def is_non_degenerate(a, b, c):
    """Checks if sides a, b, c form a non-degenerate triangle."""
    return (a + b > c) and (a + c > b) and (b + c > a)

a, b, c = 100, 1, 1
is_valid = is_non_degenerate(a, b, c)
print(f"Is (100, 1, 1) a non-degenerate triangle? {is_valid}")
